// because both paths flattened to the same NUL-joined key; w is mid-backoff.
// The shared flattened key is: "a" NUL "b" NUL "c" NUL "7".
func legacyCollisionEntries() []*logEntry {
	key := legacyNonceKey("a\x00b", "c", 7)
