		t.Fatalf("submit must also be refused on the broken instance, got %v", err)
	}
	if got, ok := q.Query("first"); !ok || got.Status != StatusWaiting {
		t.Fatalf("query must remain available and show waiting first: %+v ok=%v", got, ok)
	}
}

